// ── Función para obtener ejercicios por nivel y tipo ──────────────────────────
export function obtenerEjerciciosPorNivel(nivelIndex: number): {
  ordenar: EjercicioOrdenar[];
  verdaderoFalso: EjercicioVerdaderoFalso[];
  relacionar: EjercicioRelacionar[];
} {
  switch (nivelIndex) {
    case 0:
      return { ordenar: ordenarNivel0, verdaderoFalso: verdaderoFalsoNivel0, relacionar: relacionarNivel0 };
    case 1:
      return { ordenar: ordenarA1, verdaderoFalso: verdaderoFalsoA1, relacionar: relacionarA1 };
    case 2:
      return { ordenar: ordenarA2, verdaderoFalso: verdaderoFalsoA2, relacionar: relacionarA2 };
    case 3:
      return { ordenar: ordenarB1, verdaderoFalso: verdaderoFalsoB1, relacionar: relacionarB1 };
    case 4:
      return { ordenar: ordenarB2, verdaderoFalso: verdaderoFalsoB2, relacionar: relacionarB2 };
    case 5:
      return { ordenar: ordenarC1, verdaderoFalso: verdaderoFalsoC1, relacionar: relacionarC1 };
    default:
      // Fallback de seguridad, no debería ocurrir con los 6 niveles definidos
      return { ordenar: ordenarNivel0, verdaderoFalso: verdaderoFalsoNivel0, relacionar: relacionarNivel0 };
  }
}
